tip.code:
.send { transition: width .5s cubic-bezier(.65, 0, .35, 1); }
.send.busy { width: 64px; }
img { opacity: 0; scale: 1.06;
  transition: opacity .5s, scale .5s;
  transition-timing-function: cubic-bezier(.2, .7, .3, 1); }
img.loaded { opacity: 1; scale: 1; }
.toast { transition: translate .5s cubic-bezier(.2, .9, .3, 1.25);
  @starting-style { translate: 0 120%; } }
